function V.add(a, b)
  return { a[1] + b[1], a[2] + b[2], a[3] + b[3] }
end

function V.sub(a, b)
  return { a[1] - b[1], a[2] - b[2], a[3] - b[3] }
end

function V.scale(v, s)
  return { v[1] * s, v[2] * s, v[3] * s }
end

function V.dot(a, b)
  return a[1] * b[1] + a[2] * b[2] + a[3] * b[3]
end
